  it.each([
    'failed-result',
    'removed-binding',
    'old-claim',
    'changed-receipt',
    'missing-receipt',
  ] as const)('rejects %s in recovery and direct SDK evidence without replay', async (attack) => {
    const f = await fixture('tweak', false);
