                `require('node:fs').writeFileSync(${JSON.stringify(marker)}, 'started'); setTimeout(() => process.exit(0), 2500)`,
              ],
              cwdRef: '.',
              timeoutMs: 10_000,
              repeatable: true,
            },
          ],
        },
      }),
    });
    for (let attempt = 0; attempt < 100; attempt += 1) {
      if (
        await fs
          .stat(marker)
          .then(() => true)
          .catch(() => false)
      )
        break;
