  for (const [ref, content] of Object.entries(originals))
    expect(
      execFileSync('git', ['show', archiveCommit + ':' + archiveRelative + '/' + ref], {
        cwd: root,
        encoding: 'utf8',
      }),
    ).toBe(content);
});

